        ('SAT_AUG_RISK_TRAVEL_TRIP_ITINERARY', 'TRIP_NUMBER', 'NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW', 'TRIP_NO', 'trim+nullif', false)
