-- 2. MAXIMUS — SAT_ASSESSMENT_HEADER   [Implemented]  [M1]
-- standard satellite, automate_dv.sat; PK ASSESSMENT_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS [4 col(s)].
-- TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim
-- rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct ASSESSMENT_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select ASSESSMENT_HKEY as hkey,
           to_varchar(ASSESSMENT_END_TIME) as ASSESSMENT_END_TIME,
           to_varchar(ASSESSMENT_START_TIME) as ASSESSMENT_START_TIME,
           to_varchar(ASSESSMENT_STATUS) as ASSESSMENT_STATUS,
           to_varchar(REQUESTED_DATE) as REQUESTED_DATE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS'
       and ASSESSMENT_HKEY in (select hkey from s1)
    qualify rank() over (partition by ASSESSMENT_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_mt__uwr_pol_tele
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_ASSESSMENT|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("TRANSACTION_ID")), ''))),'') is not null then 'TELEVERIF:' || nullif(trim((nullif(trim(to_varchar("TRANSACTION_ID")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("END_TIME") as ASSESSMENT_END_TIME,
               to_varchar("START_TIME") as ASSESSMENT_START_TIME,
               to_varchar("TELE_VARIFICATION_STATUS") as ASSESSMENT_STATUS,
               to_varchar("TELE_VARIFICATION_INITIATED_DATE") as REQUESTED_DATE
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'ASSESSMENT_END_TIME' as column_name, 'END_TIME' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.ASSESSMENT_END_TIME, e.ASSESSMENT_END_TIME) then 0
                when c.ASSESSMENT_END_TIME is null and nullif(trim(e.ASSESSMENT_END_TIME), '') is null then 1
                when c.ASSESSMENT_END_TIME = trim(e.ASSESSMENT_END_TIME) then 2
                when upper(c.ASSESSMENT_END_TIME) = upper(trim(e.ASSESSMENT_END_TIME)) then 3
                when try_to_decimal(c.ASSESSMENT_END_TIME, 38, 10) = try_to_decimal(trim(e.ASSESSMENT_END_TIME), 38, 10) then 4
                when try_to_timestamp_ntz(c.ASSESSMENT_END_TIME) = try_to_timestamp_ntz(trim(e.ASSESSMENT_END_TIME)) then 5
                when length(c.ASSESSMENT_END_TIME) < length(e.ASSESSMENT_END_TIME) and startswith(e.ASSESSMENT_END_TIME, c.ASSESSMENT_END_TIME) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ASSESSMENT_END_TIME
    union all
    select 'ASSESSMENT_START_TIME' as column_name, 'START_TIME' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.ASSESSMENT_START_TIME, e.ASSESSMENT_START_TIME) then 0
                when c.ASSESSMENT_START_TIME is null and nullif(trim(e.ASSESSMENT_START_TIME), '') is null then 1
                when c.ASSESSMENT_START_TIME = trim(e.ASSESSMENT_START_TIME) then 2
                when upper(c.ASSESSMENT_START_TIME) = upper(trim(e.ASSESSMENT_START_TIME)) then 3
                when try_to_decimal(c.ASSESSMENT_START_TIME, 38, 10) = try_to_decimal(trim(e.ASSESSMENT_START_TIME), 38, 10) then 4
                when try_to_timestamp_ntz(c.ASSESSMENT_START_TIME) = try_to_timestamp_ntz(trim(e.ASSESSMENT_START_TIME)) then 5
                when length(c.ASSESSMENT_START_TIME) < length(e.ASSESSMENT_START_TIME) and startswith(e.ASSESSMENT_START_TIME, c.ASSESSMENT_START_TIME) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ASSESSMENT_START_TIME
    union all
    select 'ASSESSMENT_STATUS' as column_name, 'TELE_VARIFICATION_STATUS' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.ASSESSMENT_STATUS, e.ASSESSMENT_STATUS) then 0
                when c.ASSESSMENT_STATUS is null and nullif(trim(e.ASSESSMENT_STATUS), '') is null then 1
                when c.ASSESSMENT_STATUS = trim(e.ASSESSMENT_STATUS) then 2
                when upper(c.ASSESSMENT_STATUS) = upper(trim(e.ASSESSMENT_STATUS)) then 3
                when try_to_decimal(c.ASSESSMENT_STATUS, 38, 10) = try_to_decimal(trim(e.ASSESSMENT_STATUS), 38, 10) then 4
                when try_to_timestamp_ntz(c.ASSESSMENT_STATUS) = try_to_timestamp_ntz(trim(e.ASSESSMENT_STATUS)) then 5
                when length(c.ASSESSMENT_STATUS) < length(e.ASSESSMENT_STATUS) and startswith(e.ASSESSMENT_STATUS, c.ASSESSMENT_STATUS) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ASSESSMENT_STATUS
    union all
    select 'REQUESTED_DATE' as column_name, 'TELE_VARIFICATION_INITIATED_DATE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.REQUESTED_DATE, e.REQUESTED_DATE) then 0
                when c.REQUESTED_DATE is null and nullif(trim(e.REQUESTED_DATE), '') is null then 1
                when c.REQUESTED_DATE = trim(e.REQUESTED_DATE) then 2
                when upper(c.REQUESTED_DATE) = upper(trim(e.REQUESTED_DATE)) then 3
                when try_to_decimal(c.REQUESTED_DATE, 38, 10) = try_to_decimal(trim(e.REQUESTED_DATE), 38, 10) then 4
                when try_to_timestamp_ntz(c.REQUESTED_DATE) = try_to_timestamp_ntz(trim(e.REQUESTED_DATE)) then 5
                when length(c.REQUESTED_DATE) < length(e.REQUESTED_DATE) and startswith(e.REQUESTED_DATE, c.REQUESTED_DATE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.REQUESTED_DATE
)
select 'MAXIMUS' as project, 'SAT_ASSESSMENT_HEADER' as satellite, 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;



