               to_varchar("FRAUD_TRIGGER_TYPE") as FRAUD_TRIGGER_REASON,
               to_varchar("FRAUD_TYPE") as FRAUD_TYPE
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'FRAUD_TRIGGER_REASON' as column_name, 'FRAUD_TRIGGER_TYPE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.FRAUD_TRIGGER_REASON, e.FRAUD_TRIGGER_REASON) then 0
                when c.FRAUD_TRIGGER_REASON is null and nullif(trim(e.FRAUD_TRIGGER_REASON), '') is null then 1
                when c.FRAUD_TRIGGER_REASON = trim(e.FRAUD_TRIGGER_REASON) then 2
                when upper(c.FRAUD_TRIGGER_REASON) = upper(trim(e.FRAUD_TRIGGER_REASON)) then 3
                when try_to_decimal(c.FRAUD_TRIGGER_REASON, 38, 10) = try_to_decimal(trim(e.FRAUD_TRIGGER_REASON), 38, 10) then 4
                when try_to_timestamp_ntz(c.FRAUD_TRIGGER_REASON) = try_to_timestamp_ntz(trim(e.FRAUD_TRIGGER_REASON)) then 5
                when length(c.FRAUD_TRIGGER_REASON) < length(e.FRAUD_TRIGGER_REASON) and startswith(e.FRAUD_TRIGGER_REASON, c.FRAUD_TRIGGER_REASON) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.FRAUD_TRIGGER_REASON
    union all
    select 'FRAUD_TYPE' as column_name, 'FRAUD_TYPE' as raw_column, 'trim+nullif' as model_rule,
