     order by hkey
     limit 100
),
c4 as (  -- latest satellite row per sampled key
    select CLAIM_HKEY as hkey,
           to_varchar(NOTIFICATION_DATE) as NOTIFICATION_DATE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
       and CLAIM_HKEY in (select hkey from s4)
    qualify rank() over (partition by CLAIM_HKEY order by LOAD_DATETIME desc) = 1
),
