                when c.EMPLOYEE_CODE is null and nullif(trim(e.EMPLOYEE_CODE), '') is null then 1
                when c.EMPLOYEE_CODE = trim(e.EMPLOYEE_CODE) then 2
                when upper(c.EMPLOYEE_CODE) = upper(trim(e.EMPLOYEE_CODE)) then 3
