----------------------------------------------------------------------------------------
-- 67. MAXIMUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]  [M1]
-- standard satellite, automate_dv.sat; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [4 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [6 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(EDUCATIONAL_QUALIFICATION) as EDUCATIONAL_QUALIFICATION,
           to_varchar(FATHER_NAME) as FATHER_NAME,
           to_varchar(MARITAL_STATUS) as MARITAL_STATUS,
           to_varchar(SPOUSE_NAME) as SPOUSE_NAME
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_mbr_pp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when nullif(trim(w0_party_code),'') is not null then nullif(trim(w0_party_code), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("EDUCATION") as EDUCATIONAL_QUALIFICATION,
               to_varchar("FATHER_NAME") as FATHER_NAME,
               to_varchar("MARITAL_STATUS") as MARITAL_STATUS,
               to_varchar("SPOUSE_NAME") as SPOUSE_NAME
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'EDUCATIONAL_QUALIFICATION' as column_name, 'EDUCATION' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.EDUCATIONAL_QUALIFICATION, e.EDUCATIONAL_QUALIFICATION) then 0
                when c.EDUCATIONAL_QUALIFICATION is null and nullif(trim(e.EDUCATIONAL_QUALIFICATION), '') is null then 1
                when c.EDUCATIONAL_QUALIFICATION = trim(e.EDUCATIONAL_QUALIFICATION) then 2
                when upper(c.EDUCATIONAL_QUALIFICATION) = upper(trim(e.EDUCATIONAL_QUALIFICATION)) then 3
                when try_to_decimal(c.EDUCATIONAL_QUALIFICATION, 38, 10) = try_to_decimal(trim(e.EDUCATIONAL_QUALIFICATION), 38, 10) then 4
                when try_to_timestamp_ntz(c.EDUCATIONAL_QUALIFICATION) = try_to_timestamp_ntz(trim(e.EDUCATIONAL_QUALIFICATION)) then 5
                when length(c.EDUCATIONAL_QUALIFICATION) < length(e.EDUCATIONAL_QUALIFICATION) and startswith(e.EDUCATIONAL_QUALIFICATION, c.EDUCATIONAL_QUALIFICATION) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.EDUCATIONAL_QUALIFICATION
    union all
    select 'FATHER_NAME' as column_name, 'FATHER_NAME' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.FATHER_NAME, e.FATHER_NAME) then 0
                when c.FATHER_NAME is null and nullif(trim(e.FATHER_NAME), '') is null then 1
                when c.FATHER_NAME = trim(e.FATHER_NAME) then 2
                when upper(c.FATHER_NAME) = upper(trim(e.FATHER_NAME)) then 3
                when try_to_decimal(c.FATHER_NAME, 38, 10) = try_to_decimal(trim(e.FATHER_NAME), 38, 10) then 4
                when try_to_timestamp_ntz(c.FATHER_NAME) = try_to_timestamp_ntz(trim(e.FATHER_NAME)) then 5
                when length(c.FATHER_NAME) < length(e.FATHER_NAME) and startswith(e.FATHER_NAME, c.FATHER_NAME) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.FATHER_NAME
    union all
    select 'MARITAL_STATUS' as column_name, 'MARITAL_STATUS' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.MARITAL_STATUS, e.MARITAL_STATUS) then 0
                when c.MARITAL_STATUS is null and nullif(trim(e.MARITAL_STATUS), '') is null then 1
                when c.MARITAL_STATUS = trim(e.MARITAL_STATUS) then 2
                when upper(c.MARITAL_STATUS) = upper(trim(e.MARITAL_STATUS)) then 3
                when try_to_decimal(c.MARITAL_STATUS, 38, 10) = try_to_decimal(trim(e.MARITAL_STATUS), 38, 10) then 4
                when try_to_timestamp_ntz(c.MARITAL_STATUS) = try_to_timestamp_ntz(trim(e.MARITAL_STATUS)) then 5
