----------------------------------------------------------------------------------------
-- 83. MAXIMUS — SAT_POLICY_INTERMEDIARY_SPLIT   [Implemented]  [M2]
-- standard satellite, automate_dv.ma_sat; PK POLICY_HKEY, child key
-- INTERMEDIARY_REFERENCE; 2 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS [1 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_INTERMEDIARY_SPLIT
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(INTERMEDIARY_REFERENCE) as cdk_1,
           to_varchar(COMMISSION_AMOUNT) as COMMISSION_AMOUNT
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_INTERMEDIARY_SPLIT
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS'
       and POLICY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_HKEY, INTERMEDIARY_REFERENCE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_mt__uwr_pol
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("POLICY_NUMBER")), ''))),'') is not null then nullif(trim((nullif(trim(to_varchar("POLICY_NUMBER")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
               to_varchar(coalesce('AGENT:' || nullif(trim((nullif(trim(to_varchar("AGENT_CODE")), ''))), ''),'')) as cdk_1,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("COMMISION") as COMMISSION_AMOUNT
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r1 as (
    select 'COMMISSION_AMOUNT' as column_name, 'COMMISION' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.COMMISSION_AMOUNT, e.COMMISSION_AMOUNT) then 0
                when c.COMMISSION_AMOUNT is null and nullif(trim(e.COMMISSION_AMOUNT), '') is null then 1
                when c.COMMISSION_AMOUNT = trim(e.COMMISSION_AMOUNT) then 2
                when upper(c.COMMISSION_AMOUNT) = upper(trim(e.COMMISSION_AMOUNT)) then 3
                when try_to_decimal(c.COMMISSION_AMOUNT, 38, 10) = try_to_decimal(trim(e.COMMISSION_AMOUNT), 38, 10) then 4
                when try_to_timestamp_ntz(c.COMMISSION_AMOUNT) = try_to_timestamp_ntz(trim(e.COMMISSION_AMOUNT)) then 5
                when length(c.COMMISSION_AMOUNT) < length(e.COMMISSION_AMOUNT) and startswith(e.COMMISSION_AMOUNT, c.COMMISSION_AMOUNT) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.COMMISSION_AMOUNT
),
s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_INTERMEDIARY_SPLIT
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     order by hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
