                when c.GROSS_PREMIUM is null and nullif(trim(e.GROSS_PREMIUM), '') is null then 1
                when c.GROSS_PREMIUM = trim(e.GROSS_PREMIUM) then 2
                when upper(c.GROSS_PREMIUM) = upper(trim(e.GROSS_PREMIUM)) then 3
