      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r1 as (
    select 'CLAIMED_AMOUNT_BREAKUP' as column_name, 'BILL_BREAKUP' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.CLAIMED_AMOUNT_BREAKUP, e.CLAIMED_AMOUNT_BREAKUP) then 0
                when c.CLAIMED_AMOUNT_BREAKUP is null and nullif(trim(e.CLAIMED_AMOUNT_BREAKUP), '') is null then 1
                when c.CLAIMED_AMOUNT_BREAKUP = trim(e.CLAIMED_AMOUNT_BREAKUP) then 2
                when upper(c.CLAIMED_AMOUNT_BREAKUP) = upper(trim(e.CLAIMED_AMOUNT_BREAKUP)) then 3
                when try_to_decimal(c.CLAIMED_AMOUNT_BREAKUP, 38, 10) = try_to_decimal(trim(e.CLAIMED_AMOUNT_BREAKUP), 38, 10) then 4
                when try_to_timestamp_ntz(c.CLAIMED_AMOUNT_BREAKUP) = try_to_timestamp_ntz(trim(e.CLAIMED_AMOUNT_BREAKUP)) then 5
                when length(c.CLAIMED_AMOUNT_BREAKUP) < length(e.CLAIMED_AMOUNT_BREAKUP) and startswith(e.CLAIMED_AMOUNT_BREAKUP, c.CLAIMED_AMOUNT_BREAKUP) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.CLAIMED_AMOUNT_BREAKUP
    union all
