                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.DEDUCTION_AMOUNT_BREAKUP
    union all
