-- 116. MAXIMUS — SAT_AUG_CLAIM_FRAUD   [Implemented]  [M2]
-- augmented satellite, automate_dv.sat; PK CLAIM_HKEY; 4 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [5 col(s)],
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW [6
-- col(s)],
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [5 col(s)],
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW
-- [2 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_CLAIM_FRAUD
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select CLAIM_HKEY as hkey,
           to_varchar(FRAUD_APPROVER_REFERENCE) as FRAUD_APPROVER_REFERENCE,
           to_varchar(FRAUD_APPROVER_REMARKS) as FRAUD_APPROVER_REMARKS,
           to_varchar(FRAUD_CLASSIFICATION) as FRAUD_CLASSIFICATION,
           to_varchar(FRAUD_REFERRAL_RAISED_BY_REFERENCE) as FRAUD_REFERRAL_RAISED_BY_REFERENCE,
           to_varchar(FRAUD_SEVERITY) as FRAUD_SEVERITY
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_CLAIM_FRAUD
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
       and CLAIM_HKEY in (select hkey from s1)
    qualify rank() over (partition by CLAIM_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clma_msp_msd_prop_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("FRAUD_APPROVER") as FRAUD_APPROVER_REFERENCE,
               to_varchar("FRAUD_APPROVER_REMARKS") as FRAUD_APPROVER_REMARKS,
               to_varchar("FRAUD_CLASSIFICATION") as FRAUD_CLASSIFICATION,
               to_varchar("FRAUD_REQUESTED_BY") as FRAUD_REFERRAL_RAISED_BY_REFERENCE,
               to_varchar("SEVERITY_OF_FRAUD") as FRAUD_SEVERITY
