                when length(c.AOL_MODE_CODE) < length(e.AOL_MODE_CODE) and startswith(e.AOL_MODE_CODE, c.AOL_MODE_CODE) then 6
                else 7 end) as cls
      from c2 c left join e2 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
