----------------------------------------------------------------------------------------
-- 123. MAXIMUS — SAT_AUG_CLAIM_QUALITY_AUDIT   [Implemented]  [M2]
-- augmented satellite, automate_dv.sat; PK CLAIM_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW [1
-- col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_CLAIM_QUALITY_AUDIT
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select CLAIM_HKEY as hkey,
           to_varchar(FLAGGED_FOR_AUDIT_INDICATOR) as FLAGGED_FOR_AUDIT_INDICATOR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_CLAIM_QUALITY_AUDIT
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
       and CLAIM_HKEY in (select hkey from s1)
    qualify rank() over (partition by CLAIM_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmap_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),''), nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), ''), nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("FLAG_FOR_AUDIT") as FLAGGED_FOR_AUDIT_INDICATOR
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'FLAGGED_FOR_AUDIT_INDICATOR' as column_name, 'FLAG_FOR_AUDIT' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.FLAGGED_FOR_AUDIT_INDICATOR, e.FLAGGED_FOR_AUDIT_INDICATOR) then 0
                when c.FLAGGED_FOR_AUDIT_INDICATOR is null and nullif(trim(e.FLAGGED_FOR_AUDIT_INDICATOR), '') is null then 1
