----------------------------------------------------------------------------------------
-- 179. MAXIMUS — SAT_AUG_POLICY_TERMS   [Implemented]  [M3]
-- augmented satellite, automate_dv.sat; PK POLICY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [7 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_TERMS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(CUSTOMISED_PRODUCT_INDICATOR) as CUSTOMISED_PRODUCT_INDICATOR,
           to_varchar(EXCLUDED_COUNTRIES_DESCRIPTION) as EXCLUDED_COUNTRIES_DESCRIPTION,
           to_varchar(EXCLUDED_COUNTRIES_REMARKS) as EXCLUDED_COUNTRIES_REMARKS,
           to_varchar(EXCLUDED_EVENTS_DESCRIPTION) as EXCLUDED_EVENTS_DESCRIPTION,
           to_varchar(EXCLUDED_EVENTS_REMARKS) as EXCLUDED_EVENTS_REMARKS,
           to_varchar(MANDATORY_QUESTIONNAIRE_INDICATOR) as MANDATORY_QUESTIONNAIRE_INDICATOR,
           to_varchar(UNDERWRITING_RULES_BYPASSED_INDICATOR) as UNDERWRITING_RULES_BYPASSED_INDICATOR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_TERMS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and POLICY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_polp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(w0_policy_number),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_policy_number), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("CUSTOMIZED") as CUSTOMISED_PRODUCT_INDICATOR,
               to_varchar("EXCLUDED_COUNTRY_DETAILS") as EXCLUDED_COUNTRIES_DESCRIPTION,
