-- 188. MAXIMUS — SAT_AUG_QUOTE_COVERAGE_SCHEDULE   [Implemented]  [M3]
-- augmented satellite, automate_dv.ma_sat; PK QUOTE_HKEY, child key COVERAGE_REFERENCE;
-- 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW
-- [9 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct QUOTE_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_COVERAGE_SCHEDULE
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select QUOTE_HKEY as hkey,
           to_varchar(COVERAGE_REFERENCE) as cdk_1,
           to_varchar(COVERAGE_DURATION) as COVERAGE_DURATION,
           to_varchar(DELAY_TRIGGER_THRESHOLD) as DELAY_TRIGGER_THRESHOLD,
           to_varchar(PREMIUM_BASIS) as PREMIUM_BASIS,
           to_varchar(SUB_COVER_SELECTION) as SUB_COVER_SELECTION,
           to_varchar(DEDUCTIBLE_AMOUNT) as DEDUCTIBLE_AMOUNT,
           to_varchar(EXCLUDED_COUNTRIES) as EXCLUDED_COUNTRIES,
           to_varchar(EXCLUDED_EVENTS) as EXCLUDED_EVENTS,
           to_varchar(ITEMS_COVERED) as ITEMS_COVERED,
           to_varchar(SUM_INSURED_AMOUNT) as SUM_INSURED_AMOUNT
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_COVERAGE_SCHEDULE
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW'
       and QUOTE_HKEY in (select hkey from s1)
    qualify rank() over (partition by QUOTE_HKEY, COVERAGE_REFERENCE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via up_mt__uwr_qpd_polp_msp_imsd_inp_pv__aug_sat_aug_quote_coverage_schedule#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_QUOTE|' || (((nullif(trim(case when nullif(trim(w0_policy_quote_number),'') is not null then nullif(trim(w0_policy_quote_number), '') end),'')))) AS VARCHAR))), '')) as hkey,
               to_varchar('ACE') as cdk_1,
               rec_refresh_at as ldts,
               to_varchar("ACE_DURATION") as COVERAGE_DURATION,
               to_varchar("DELAY_EXCEEDING_ACE") as DELAY_TRIGGER_THRESHOLD,
               to_varchar("ACE_PREMIUM_TYPE") as PREMIUM_BASIS,
               cast(null as varchar) as SUB_COVER_SELECTION,
               cast(null as varchar) as DEDUCTIBLE_AMOUNT,
               cast(null as varchar) as EXCLUDED_COUNTRIES,
               cast(null as varchar) as EXCLUDED_EVENTS,
