s6 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct QUOTE_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST'
     order by hkey
     limit 100
),
c6 as (  -- latest satellite row per sampled key
    select QUOTE_HKEY as hkey,
           to_varchar(SOURCE_POLICY_IDENTIFIER) as SOURCE_POLICY_IDENTIFIER
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST'
       and QUOTE_HKEY in (select hkey from s6)
    qualify rank() over (partition by QUOTE_HKEY order by LOAD_DATETIME desc) = 1
),
e6 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_qpd_rskl
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_QUOTE|' || (nullif(trim(case when nullif(trim(w0_policy_quote_number),'') is not null then nullif(trim(w0_policy_quote_number), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("POLICY_ID") as SOURCE_POLICY_IDENTIFIER
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST
      )
     where hkey in (select hkey from s6) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r6 as (
    select 'SOURCE_POLICY_IDENTIFIER' as column_name, 'POLICY_ID' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.SOURCE_POLICY_IDENTIFIER, e.SOURCE_POLICY_IDENTIFIER) then 0
                when c.SOURCE_POLICY_IDENTIFIER is null and nullif(trim(e.SOURCE_POLICY_IDENTIFIER), '') is null then 1
                when c.SOURCE_POLICY_IDENTIFIER = trim(e.SOURCE_POLICY_IDENTIFIER) then 2
                when upper(c.SOURCE_POLICY_IDENTIFIER) = upper(trim(e.SOURCE_POLICY_IDENTIFIER)) then 3
                when try_to_decimal(c.SOURCE_POLICY_IDENTIFIER, 38, 10) = try_to_decimal(trim(e.SOURCE_POLICY_IDENTIFIER), 38, 10) then 4
                when try_to_timestamp_ntz(c.SOURCE_POLICY_IDENTIFIER) = try_to_timestamp_ntz(trim(e.SOURCE_POLICY_IDENTIFIER)) then 5
                when length(c.SOURCE_POLICY_IDENTIFIER) < length(e.SOURCE_POLICY_IDENTIFIER) and startswith(e.SOURCE_POLICY_IDENTIFIER, c.SOURCE_POLICY_IDENTIFIER) then 6
                else 7 end) as cls
      from c6 c left join e6 e on e.hkey = c.hkey
     group by c.hkey, c.SOURCE_POLICY_IDENTIFIER
),
s7 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct QUOTE_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY'
     order by hkey
     limit 100
),
c7 as (  -- latest satellite row per sampled key
    select QUOTE_HKEY as hkey,
           to_varchar(QUOTE_CAPTURE_EVENT_CODE) as QUOTE_CAPTURE_EVENT_CODE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY'
