s3 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct QUOTE_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_RATING
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW'
     order by hkey
     limit 100
),
c3 as (  -- latest satellite row per sampled key
    select QUOTE_HKEY as hkey,
           to_varchar(PREMIUM_ADJUSTMENT_AMOUNT) as PREMIUM_ADJUSTMENT_AMOUNT,
           to_varchar(PREMIUM_ADJUSTMENT_TYPE) as PREMIUM_ADJUSTMENT_TYPE,
           to_varchar(PREMIUM_AMOUNT_IN_BHD) as PREMIUM_AMOUNT_IN_BHD,
           to_varchar(PREMIUM_COLLECTED_AMOUNT) as PREMIUM_COLLECTED_AMOUNT,
