           to_varchar(TOTAL_PREMIUM_DUE) as TOTAL_PREMIUM_DUE,
           to_varchar(TOTAL_TAX_AMOUNT) as TOTAL_TAX_AMOUNT,
           to_varchar(TRAVELLING_COMPANION_DISCOUNT_AMOUNT) as TRAVELLING_COMPANION_DISCOUNT_AMOUNT
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_RATING
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW'
       and QUOTE_HKEY in (select hkey from s3)
    qualify rank() over (partition by QUOTE_HKEY order by LOAD_DATETIME desc) = 1
),
e3 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_qpd_rskl_rskp_rl_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_QUOTE|' || (nullif(trim(case when nullif(trim(w0_policy_quote_number),'') is not null then nullif(trim(w0_policy_quote_number), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar("PREMIUM_ADJUSTMENT") as PREMIUM_ADJUSTMENT_AMOUNT,
