                when length(c.GROSS_PREMIUM) < length(e.GROSS_PREMIUM) and startswith(e.GROSS_PREMIUM, c.GROSS_PREMIUM) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.GROSS_PREMIUM
